// ═══════════════════════════════════════════════════════════════════════════════
// Types & constants
// ═══════════════════════════════════════════════════════════════════════════════

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

// Wider canvas that uses the full rich-diagram center column.  Two-column layout
// keeps the vertical height close to the viewport so fitToView only scales down
// to ~0.8x instead of the previous ~0.45x, making every shape and label readable.
const W = 1200;
const CX = W / 2;
const CX_L = 300;   // left column center
const CX_R = 900;   // right column center

const COLORS = {
  input: { fill: '#e8f5e9', stroke: '#4caf50' },
  gate: { fill: '#e3f2fd', stroke: '#1976d2' },
  softmax: { fill: '#fff8e1', stroke: '#f9a825' },
  topk: { fill: '#fce4ec', stroke: '#d81b60' },
  dispatch: { fill: '#ede9fe', stroke: '#7c3aed' },
  expert: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  combine: { fill: '#e0f2f1', stroke: '#009688' },
  output: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  weight: { fill: '#f1f5f9', stroke: '#64748b' },
  text: 'var(--text)',
  muted: 'var(--text-muted)',
};

const STEP_GROUPS = {
  input: 'step-moe-input',
  gate: 'step-moe-gate',
  softmax: 'step-moe-softmax',
  topk: 'step-moe-topk',
  dispatch: 'step-moe-dispatch',
  combine: 'step-moe-combine',
  output: 'step-moe-output',
};

// Generous but height-aware spacing
const HEADER_H = 48;
const HEADER_W = 540;
const MAT_H = 80;
const VEC_H = 34;
const VEC_W = 160;
const WEIGHT_W = 140;
const SEQ_W = 160;
const GROUP_GAP = 34;
const HEADER_TO_ROW_GAP = 26;
const ROW_EQ_GAP = 48;

