// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(
  g: Gsel,
  x: number,
  y: number,
  text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function arrowH(g: Gsel, x1: number, x2: number, y: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function stepHeader(
  g: Gsel,
  cx: number,
  y: number,
  stepNum: number,
  title: string,
  formula: string,
  fill: string,
  stroke: string
): number {
  const grp = g.append('g');
  grp
    .append('rect')
    .attr('x', cx - HEADER_W / 2)
    .attr('y', y)
    .attr('width', HEADER_W)
    .attr('height', HEADER_H)
    .attr('rx', 8)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);

  // step badge
  grp.append('circle')
    .attr('cx', cx - HEADER_W / 2 + 24)
    .attr('cy', y + HEADER_H / 2)
    .attr('r', 14)
    .attr('fill', stroke);
  lbl(grp, cx - HEADER_W / 2 + 24, y + HEADER_H / 2 + 1, String(stepNum), { size: 13, weight: '700', color: '#fff' });

  lbl(grp, cx - HEADER_W / 2 + 50, y + HEADER_H / 2 - 1, title, { size: 15, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(grp, cx + HEADER_W / 2 - 14, y + HEADER_H / 2 - 1, formula, {
    size: 12,
    color: 'var(--text-muted)',
    font: 'monospace',
    anchor: 'end'
  });
  return y + HEADER_H;
}

function startGroup(_g: Gsel, className: string, step: number): Gsel {
  return _g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(step));
}

// ═══════════════════════════════════════════════════════════════════════════════
// Matrix helpers (all center-based)
// ═══════════════════════════════════════════════════════════════════════════════

function drawSeqMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.input.fill,
  stroke = COLORS.input.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - MAT_H / 2, {
    width: SEQ_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 6,
    rows: 5,
    dimTop: 'D',
    dimRight: 'S',
  });
}

function drawScoreMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.softmax.fill,
  stroke = COLORS.softmax.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - MAT_H / 2, {
    width: SEQ_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 4,
    rows: 5,
    dimTop: 'E',
    dimRight: 'S',
  });
}

function drawWeightMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.weight.fill,
  stroke = COLORS.weight.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - MAT_H / 2, {
    width: WEIGHT_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 4,
    rows: 5,
  });
}

function drawSmallVector(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  width = VEC_W
): void {
  drawMatrixBlock(g as Sel, x, cy - VEC_H / 2, {
    width,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 6,
    rows: 1,
  });
}

function drawShapeEquation(g: Gsel, cx: number, cy: number, equation: string): void {
  lbl(g, cx, cy + ROW_EQ_GAP, equation, { size: 12, color: COLORS.muted, font: 'monospace' });
}

function drawMatmulRow(
  g: Gsel,
  cx: number,
  cy: number,
  leftLabel: string,
  leftShape: string,
  leftFill: string,
  leftStroke: string,
  weightLabel: string,
  weightShape: string,
  weightFill: string,
  weightStroke: string,
  rightLabel: string,
  rightShape: string,
  rightFill: string,
  rightStroke: string,
  equation: string
): number {
  const leftX = cx - 200;
  const weightX = cx - 10;
  const rightX = cx + 180;

  drawSmallVector(g, leftX, cy, leftLabel, leftShape, leftFill, leftStroke);
  drawWeightMatrix(g, weightX, cy, weightLabel, weightShape, weightFill, weightStroke);
  drawSmallVector(g, rightX, cy, rightLabel, rightShape, rightFill, rightStroke);

  const opX = cx + 50;
  g.append('circle').attr('cx', opX).attr('cy', cy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);
  lbl(g, opX, cy, '@', { size: 13, weight: '700', color: '#64748b' });

  arrowH(g, leftX + VEC_W, opX - 14, cy, leftStroke);
  arrowH(g, weightX + WEIGHT_W, opX - 14, cy, weightStroke);
  arrowH(g, opX + 14, rightX, cy, rightStroke);

  drawShapeEquation(g, cx, cy, equation);
  return cy + MAT_H / 2 + ROW_EQ_GAP + 10;
}

function drawParamSummary(g: Gsel, cx: number, y: number, dModel: number, seqLen: number, nExperts: number, topK: number, routing: string): number {
  const SUM_W = 1120;
  const SUM_H = 68;
  const grp = g.append('g').attr('transform', `translate(${cx - SUM_W / 2}, ${y})`);
  grp.append('rect').attr('width', SUM_W).attr('height', SUM_H).attr('rx', 8)
    .attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 1);
  lbl(grp, 16, 20, 'Parameters →', { size: 10, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model = ${dModel}`, dim: 'hidden dim', color: '#4caf50' },
    { label: `seq_len = ${seqLen}`, dim: 'tokens', color: '#1976d2' },
    { label: `n_experts = ${nExperts}`, dim: 'experts', color: '#7c3aed' },
    { label: `top_k = ${topK}`, dim: 'selected', color: '#d81b60' },
    { label: `routing = ${routing.replace(/-/g, ' ')}`, dim: 'strategy', color: '#009688' },
  ];
  const itemW = 214;
  const startX = 16;
  items.forEach((item, i) => {
    const px = startX + i * itemW;
    grp.append('rect').attr('x', px).attr('y', 28).attr('width', itemW - 6).attr('height', 32).attr('rx', 6)
      .attr('fill', hexWithAlpha(item.color, 0.08)).attr('stroke', item.color).attr('stroke-width', 1);
    lbl(grp, px + 9, 46, item.label, { size: 10, weight: '600', color: item.color, font: 'monospace', anchor: 'start' });
    lbl(grp, px + 9, 58, `→ ${item.dim}`, { size: 8, color: item.color, anchor: 'start' });
  });
  return y + SUM_H + 14;
}

function hexWithAlpha(hex: string, alpha: number): string {
  const v = hex.replace('#', '');
  const bigint = parseInt(v, 16);
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// MoE-specific layout helpers
// ═══════════════════════════════════════════════════════════════════════════════

function drawTopKMatrix(
  g: Gsel,
  cx: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  selectedPerRow: number,
  transpose = false
): number {
  const matW = SEQ_W;
  const matH = MAT_H;
  const matX = cx - matW / 2;
  const matY = cy - matH / 2;

  drawMatrixBlock(g as Sel, matX, matY, {
    width: matW,
    height: matH,
    label,
    sublabel,
    fill,
    stroke,
    cols: transpose ? 5 : 4,
    rows: transpose ? 4 : 5,
    dimTop: transpose ? 'S' : 'E',
    dimRight: transpose ? 'E' : 'S',
  });

  const cols = transpose ? 5 : 4;
  const rows = transpose ? 4 : 5;
  const cellW = matW / cols;
  const cellH = matH / rows;
  const pad = 2;

  for (let r = 0; r < rows; r++) {
    for (let k = 0; k < selectedPerRow; k++) {
      const c = transpose ? ((r + k * 2 + 1) % cols) : ((r + k * 2 + 1) % cols);
      g.append('rect')
        .attr('x', matX + c * cellW + pad)
        .attr('y', matY + r * cellH + pad)
        .attr('width', cellW - pad * 2)
        .attr('height', cellH - pad * 2)
        .attr('rx', 2)
        .attr('fill', stroke)
        .attr('opacity', 0.28)
        .attr('stroke', stroke)
        .attr('stroke-width', 1.2);
    }
  }

  return cy + MAT_H / 2 + ROW_EQ_GAP + 10;
}

function drawSmallIndexWeightVectors(
  g: Gsel,
  cx: number,
  cy: number,
  topK: number,
  variant: 'token' | 'expert'
): number {
  const leftX = cx - 166;
  const rightX = cx + 6;
  const shape = variant === 'token' ? '[S, K]' : '[E, K]';

  drawSmallVector(g, leftX, cy, 'indices', shape, COLORS.topk.fill, COLORS.topk.stroke);
  drawSmallVector(g, rightX, cy, 'weights', shape, COLORS.softmax.fill, COLORS.softmax.stroke);

  lbl(g, cx, cy + 32, `top-${topK} ${variant === 'token' ? 'experts per token' : 'tokens per expert'}`, {
    size: 12,
    color: COLORS.muted,
    font: 'monospace',
  });
  return cy + 56;
}

function drawExpertBoxes(g: Gsel, cx: number, y: number, nExperts: number): number {
  const shownExperts = Math.min(nExperts, 4);
  const boxW = 120;
  const boxH = 72;
  const gap = 16;
  const totalW = shownExperts * boxW + (shownExperts - 1) * gap;
  const startX = cx - totalW / 2;

  for (let i = 0; i < shownExperts; i++) {
    const x = startX + i * (boxW + gap);
    const eg = g.append('g');
    eg.append('rect')
      .attr('x', x).attr('y', y)
      .attr('width', boxW).attr('height', boxH).attr('rx', 8)
      .attr('fill', COLORS.expert.fill).attr('stroke', COLORS.expert.stroke).attr('stroke-width', 1.5);
    eg.append('rect')
      .attr('x', x + 12).attr('y', y + 36)
      .attr('width', boxW - 24).attr('height', 24).attr('rx', 5)
      .attr('fill', '#fff').attr('stroke', COLORS.expert.stroke).attr('stroke-width', 1);
    lbl(eg, x + boxW / 2, y + 22, `Expert ${i + 1}`, { size: 13, weight: '600', color: COLORS.expert.stroke });
    lbl(eg, x + boxW / 2, y + 50, 'FFN  [S, D] → [S, D]', { size: 10, color: COLORS.muted, font: 'monospace' });
  }

  if (nExperts > shownExperts) {
    lbl(g, cx, y + boxH + 22, `… + ${nExperts - shownExperts} more experts`, { size: 11, color: COLORS.muted });
    return y + boxH + 44;
  }
  return y + boxH + 22;
}

function drawDispatchArrows(g: Gsel, cx: number, fromY: number, toY: number, nExperts: number): void {
  const shownExperts = Math.min(nExperts, 4);
  const boxW = 120;
  const gap = 16;
  const totalW = shownExperts * boxW + (shownExperts - 1) * gap;
  const startX = cx - totalW / 2;

  for (let i = 0; i < shownExperts; i++) {
    const x = startX + i * (boxW + gap) + boxW / 2;
    drawArrow(g as Sel, cx, fromY, x, toY, { color: COLORS.dispatch.stroke });
  }
}

function drawCombineRow(g: Gsel, cx: number, cy: number, nExperts: number, topK: number): number {
  const shownExperts = Math.min(nExperts, 4);
  const boxW = 120;
  const gap = 16;
  const totalW = shownExperts * boxW + (shownExperts - 1) * gap;
  const startX = cx - totalW / 2;
  const outVecW = 100; // narrower than boxW so vectors do not overlap

  for (let i = 0; i < shownExperts; i++) {
    const x = startX + i * (boxW + gap);
    drawSmallVector(g, x + (boxW - outVecW) / 2, cy, `out_${i + 1}`, '[S, D]', COLORS.expert.fill, COLORS.expert.stroke, outVecW);
  }

  const circleCy = cy + VEC_H / 2 + 32;
  g.append('circle').attr('cx', cx).attr('cy', circleCy).attr('r', 20)
    .attr('fill', '#fff').attr('stroke', COLORS.combine.stroke).attr('stroke-width', 2);
  lbl(g, cx, circleCy, 'Σ', { size: 16, weight: '700', color: COLORS.combine.stroke });

  for (let i = 0; i < shownExperts; i++) {
    const x = startX + i * (boxW + gap) + boxW / 2;
    drawArrow(g as Sel, x, cy + VEC_H / 2, cx, circleCy - 20, { color: COLORS.expert.stroke });
  }

  const outCy = circleCy + 56;
  drawSeqMatrix(g, cx - 80, outCy, 'out', '[S, D]', COLORS.combine.fill, COLORS.combine.stroke);
  arrowDown(g, cx, circleCy + 20, outCy - MAT_H / 2, COLORS.combine.stroke);

  const note = topK === 1 ? 'single expert output' : `weighted sum over top-${topK} experts`;
  lbl(g, cx, outCy + MAT_H / 2 + 18, note, { size: 12, color: COLORS.muted });
  return outCy + MAT_H / 2 + 36;
}

function crossColumnArrow(parent: Gsel, y1: number, y2: number, label: string): void {
  const x1 = CX_L + HEADER_W / 2 + 10;
  const x2 = CX_R - HEADER_W / 2 - 10;
  const midX = (x1 + x2) / 2;

  // Insert behind the step groups so it does not visually compete with shapes/labels.
  const g = parent.insert('g', ':first-child').attr('class', 'moe-cross-arrow');

  // Smooth elbow-like curve: horizontal from left, then vertical to right.
  const path = d3.path();
  path.moveTo(x1, y1);
  path.bezierCurveTo(midX - 20, y1, midX, y1 + 20, midX, (y1 + y2) / 2);
  path.bezierCurveTo(midX, y2 - 20, midX + 20, y2, x2 - 4, y2);

  g.append('path')
    .attr('d', path.toString())
    .attr('fill', 'none')
    .attr('stroke', COLORS.dispatch.stroke)
    .attr('stroke-width', 2)
    .attr('stroke-dasharray', '5,4')
    .attr('opacity', 0.7);

  // Polygon arrowhead at the right end (no extra line, so no double stroke).
  const headSize = 8;
  g.append('polygon')
    .attr('points', `${x2},${y2} ${x2 - headSize},${y2 - headSize / 2} ${x2 - headSize},${y2 + headSize / 2}`)
    .attr('fill', COLORS.dispatch.stroke)
    .attr('opacity', 0.7);

  // label pill
  const labelY = (y1 + y2) / 2;
  g.append('rect')
    .attr('x', midX - 76).attr('y', labelY - 13)
    .attr('width', 152).attr('height', 26).attr('rx', 13)
    .attr('fill', 'var(--surface)').attr('stroke', COLORS.dispatch.stroke).attr('stroke-width', 1.5);
  lbl(g, midX, labelY + 4, label, { size: 12, weight: '600', color: COLORS.dispatch.stroke });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant renderers
// ═══════════════════════════════════════════════════════════════════════════════

interface RenderResult {
  steps: MoERouterStep[];
  leftBottom: number;
  rightTop: number;
  rightBottom: number;
}

function renderTokenChoice(_g: Gsel, leftTop: number, rightTop: number, nExperts: number, topK: number): RenderResult {
  const steps: MoERouterStep[] = [];
  let yL = leftTop;
  let yR = rightTop;

  // ── Left column: score computation ──

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = startGroup(_g, STEP_GROUPS.input, 1);
  const inHeaderBottom = stepHeader(inputGrp, CX_L, yL, 1, 'Input hidden states', 'x ∈ ℝ^(S×D)', COLORS.input.fill, COLORS.input.stroke);
  const inCy = inHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(inputGrp, CX_L - 80, inCy, 'x', '[S, D]', COLORS.input.fill, COLORS.input.stroke);
  lbl(inputGrp, CX_L, inCy + MAT_H / 2 + 18, 'each row = one token embedding', { size: 12, color: COLORS.muted });
  yL = inCy + MAT_H / 2 + 28;

  // 2. Gate projection
  steps.push({ ...BASE_STEPS.gate, id: 2 });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.gate.stroke);
  yL += GROUP_GAP;
  const gateGrp = startGroup(_g, STEP_GROUPS.gate, 2);
  const gateHeaderBottom = stepHeader(gateGrp, CX_L, yL, 2, 'Gate projection', 'logits = x · W_gate', COLORS.gate.fill, COLORS.gate.stroke);
  const gateRowCy = gateHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  const gateBottom = drawMatmulRow(
    gateGrp, CX_L, gateRowCy,
    'x', '[S, D]', COLORS.input.fill, COLORS.input.stroke,
    'W_gate', '[D, E]', COLORS.weight.fill, COLORS.weight.stroke,
    'logits', '[S, E]', COLORS.gate.fill, COLORS.gate.stroke,
    '[S, D] @ [D, E] → [S, E]'
  );
  yL = gateBottom + GROUP_GAP;

  // 3. Softmax
  steps.push({
    ...BASE_STEPS.softmax,
    id: 3,
    formula: 'probs = softmax(logits, dim=-1)',
    code: { title: 'Softmax', lines: ['probs = F.softmax(logits, dim=-1)  # [S, E]'] },
  });
  arrowDown(_g, CX_L, yL - GROUP_GAP, yL, COLORS.softmax.stroke);
  const softmaxGrp = startGroup(_g, STEP_GROUPS.softmax, 3);
  const softmaxHeaderBottom = stepHeader(softmaxGrp, CX_L, yL, 3, 'Softmax over experts', 'probs = softmax(logits, dim=-1)', COLORS.softmax.fill, COLORS.softmax.stroke);
  const softmaxVecCy = softmaxHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(softmaxGrp, CX_L - 80, softmaxVecCy, 'logits', '[S, E]', COLORS.gate.fill, COLORS.gate.stroke);
  arrowDown(softmaxGrp, CX_L, softmaxVecCy + VEC_H / 2, softmaxVecCy + VEC_H / 2 + 24, COLORS.softmax.stroke);
  const softmaxMatCy = softmaxVecCy + VEC_H / 2 + 24 + MAT_H / 2;
  drawScoreMatrix(softmaxGrp, CX_L - 80, softmaxMatCy, 'probs', '[S, E]', COLORS.softmax.fill, COLORS.softmax.stroke);
  lbl(softmaxGrp, CX_L, softmaxMatCy + MAT_H / 2 + 18, 'each row sums to 1.0 across experts', { size: 11, color: COLORS.muted });
  yL = softmaxMatCy + MAT_H / 2 + 28;

  // 4. Top-k
  steps.push({
    ...BASE_STEPS.topk,
    id: 4,
    formula: 'weights, indices = topk(probs, k)',
    code: { title: 'Top-k', lines: [`weights, indices = probs.topk(${topK}, dim=-1)  # [S, ${topK}]`] },
  });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.topk.stroke);
  yL += GROUP_GAP;
  const topkGrp = startGroup(_g, STEP_GROUPS.topk, 4);
  const topkHeaderBottom = stepHeader(topkGrp, CX_L, yL, 4, 'Top-k expert selection', `weights, indices = topk(probs, ${topK})`, COLORS.topk.fill, COLORS.topk.stroke);
  const topkMatCy = topkHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawTopKMatrix(topkGrp, CX_L, topkMatCy, 'probs', `[S, E]`, COLORS.softmax.fill, COLORS.softmax.stroke, topK, false);
  const vecCy = topkMatCy + MAT_H / 2 + ROW_EQ_GAP + 18;
  const vecBottom = drawSmallIndexWeightVectors(topkGrp, CX_L, vecCy, topK, 'token');
  yL = vecBottom + GROUP_GAP;

  // ── Right column: dispatch & combine ──

  // 5. Dispatch
  steps.push({ ...BASE_STEPS.dispatch, id: 5 });
  const dispatchGrp = startGroup(_g, STEP_GROUPS.dispatch, 5);
  const dispatchHeaderBottom = stepHeader(dispatchGrp, CX_R, yR, 5, 'Dispatch to selected experts', 'tokens → top-k experts', COLORS.dispatch.fill, COLORS.dispatch.stroke);
  const expertY = dispatchHeaderBottom + HEADER_TO_ROW_GAP + 22;
  drawDispatchArrows(dispatchGrp, CX_R, dispatchHeaderBottom + HEADER_TO_ROW_GAP, expertY, nExperts);
  const expertBottom = drawExpertBoxes(dispatchGrp, CX_R, expertY, nExperts);
  yR = expertBottom + GROUP_GAP;

  // 6. Combine
  steps.push({ ...BASE_STEPS.combine, id: 6 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.combine.stroke);
  const combineGrp = startGroup(_g, STEP_GROUPS.combine, 6);
  const combineHeaderBottom = stepHeader(combineGrp, CX_R, yR, 6, 'Weighted combination', 'out = Σ weights · expert_out', COLORS.combine.fill, COLORS.combine.stroke);
  const combineCy = combineHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  const combineBottom = drawCombineRow(combineGrp, CX_R, combineCy, nExperts, topK);
  yR = combineBottom + GROUP_GAP;

  // 7. Output
  steps.push({ ...BASE_STEPS.output, id: 7 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.output.stroke);
  const outGrp = startGroup(_g, STEP_GROUPS.output, 7);
  const outHeaderBottom = stepHeader(outGrp, CX_R, yR, 7, 'Output hidden states', 'out ∈ ℝ^(S×D)', COLORS.output.fill, COLORS.output.stroke);
  const outCy = outHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(outGrp, CX_R - 80, outCy, 'out', '[S, D]', COLORS.output.fill, COLORS.output.stroke);
  yR = outCy + MAT_H / 2 + GROUP_GAP;

  return { steps, leftBottom: yL, rightTop, rightBottom: yR };
}

function renderExpertChoice(_g: Gsel, leftTop: number, rightTop: number, nExperts: number, topK: number): RenderResult {
  const steps: MoERouterStep[] = [];
  let yL = leftTop;
  let yR = rightTop;

  // ── Left column ──

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = startGroup(_g, STEP_GROUPS.input, 1);
  const inHeaderBottom = stepHeader(inputGrp, CX_L, yL, 1, 'Input hidden states', 'x ∈ ℝ^(S×D)', COLORS.input.fill, COLORS.input.stroke);
  const inCy = inHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(inputGrp, CX_L - 80, inCy, 'x', '[S, D]', COLORS.input.fill, COLORS.input.stroke);
  lbl(inputGrp, CX_L, inCy + MAT_H / 2 + 18, 'each row = one token embedding', { size: 12, color: COLORS.muted });
  yL = inCy + MAT_H / 2 + 28;

  // 2. Gate projection
  steps.push({ ...BASE_STEPS.gate, id: 2 });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.gate.stroke);
  yL += GROUP_GAP;
  const gateGrp = startGroup(_g, STEP_GROUPS.gate, 2);
  const gateHeaderBottom = stepHeader(gateGrp, CX_L, yL, 2, 'Gate projection', 'logits = x · W_gate', COLORS.gate.fill, COLORS.gate.stroke);
  const gateRowCy = gateHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  const gateBottom = drawMatmulRow(
    gateGrp, CX_L, gateRowCy,
    'x', '[S, D]', COLORS.input.fill, COLORS.input.stroke,
    'W_gate', '[D, E]', COLORS.weight.fill, COLORS.weight.stroke,
    'logits', '[S, E]', COLORS.gate.fill, COLORS.gate.stroke,
    '[S, D] @ [D, E] → [S, E]'
  );
  yL = gateBottom + GROUP_GAP;

  // 3. Softmax over tokens
  steps.push({
    ...BASE_STEPS.softmax,
    id: 3,
    label: 'Softmax over tokens',
    formula: 'probs = softmax(logits, dim=0)',
    explanation: 'Each expert normalizes its preference over all tokens.',
    code: { title: 'Softmax', lines: ['probs = F.softmax(logits, dim=0)  # [S, E]'] },
  });
  arrowDown(_g, CX_L, yL - GROUP_GAP, yL, COLORS.softmax.stroke);
  const softmaxGrp = startGroup(_g, STEP_GROUPS.softmax, 3);
  const softmaxHeaderBottom = stepHeader(softmaxGrp, CX_L, yL, 3, 'Softmax over tokens', 'probs = softmax(logits, dim=0)', COLORS.softmax.fill, COLORS.softmax.stroke);
  const softmaxVecCy = softmaxHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(softmaxGrp, CX_L - 80, softmaxVecCy, 'logits', '[S, E]', COLORS.gate.fill, COLORS.gate.stroke);
  arrowDown(softmaxGrp, CX_L, softmaxVecCy + VEC_H / 2, softmaxVecCy + VEC_H / 2 + 24, COLORS.softmax.stroke);
  const softmaxMatCy = softmaxVecCy + VEC_H / 2 + 24 + MAT_H / 2;
  drawScoreMatrix(softmaxGrp, CX_L - 80, softmaxMatCy, 'probs', '[S, E]', COLORS.softmax.fill, COLORS.softmax.stroke);
  lbl(softmaxGrp, CX_L, softmaxMatCy + MAT_H / 2 + 18, 'each column sums to 1.0 across tokens', { size: 11, color: COLORS.muted });
  yL = softmaxMatCy + MAT_H / 2 + 28;

  // 4. Top-k tokens per expert
  steps.push({
    ...BASE_STEPS.topk,
    id: 4,
    label: 'Top-k tokens per expert',
    formula: 'weights, indices = topk(probs^T, k)',
    explanation: 'Each expert selects its top-k tokens instead of each token selecting experts.',
    code: { title: 'Top-k', lines: [`weights, indices = probs.T.topk(${topK}, dim=-1)  # [E, ${topK}]`] },
  });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.topk.stroke);
  yL += GROUP_GAP;
  const topkGrp = startGroup(_g, STEP_GROUPS.topk, 4);
  const topkHeaderBottom = stepHeader(topkGrp, CX_L, yL, 4, 'Top-k tokens per expert', `weights, indices = topk(probs^T, ${topK})`, COLORS.topk.fill, COLORS.topk.stroke);
  const topkMatCy = topkHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawTopKMatrix(topkGrp, CX_L, topkMatCy, 'probs^T', `[E, S]`, COLORS.softmax.fill, COLORS.softmax.stroke, topK, true);
  const vecCy = topkMatCy + MAT_H / 2 + ROW_EQ_GAP + 18;
  const vecBottom = drawSmallIndexWeightVectors(topkGrp, CX_L, vecCy, topK, 'expert');
  yL = vecBottom + GROUP_GAP;

  // ── Right column ──

  // 5. Dispatch
  steps.push({
    ...BASE_STEPS.dispatch,
    id: 5,
    formula: 'experts → selected tokens',
    explanation: 'Each expert receives only its selected top-k tokens.',
    code: { title: 'Dispatch', lines: ['for each expert e and selected token s:', '    dispatch x[s] to expert_e'] },
  });
  const dispatchGrp = startGroup(_g, STEP_GROUPS.dispatch, 5);
  const dispatchHeaderBottom = stepHeader(dispatchGrp, CX_R, yR, 5, 'Dispatch selected tokens', 'experts → top-k tokens', COLORS.dispatch.fill, COLORS.dispatch.stroke);
  const expertY = dispatchHeaderBottom + HEADER_TO_ROW_GAP + 22;
  drawDispatchArrows(dispatchGrp, CX_R, dispatchHeaderBottom + HEADER_TO_ROW_GAP, expertY, nExperts);
  const expertBottom = drawExpertBoxes(dispatchGrp, CX_R, expertY, nExperts);
  yR = expertBottom + GROUP_GAP;

  // 6. Combine
  steps.push({ ...BASE_STEPS.combine, id: 6 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.combine.stroke);
  const combineGrp = startGroup(_g, STEP_GROUPS.combine, 6);
  const combineHeaderBottom = stepHeader(combineGrp, CX_R, yR, 6, 'Weighted combination', 'out = Σ weights · expert_out', COLORS.combine.fill, COLORS.combine.stroke);
  const combineCy = combineHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  const combineBottom = drawCombineRow(combineGrp, CX_R, combineCy, nExperts, topK);
  yR = combineBottom + GROUP_GAP;

  // 7. Output
  steps.push({ ...BASE_STEPS.output, id: 7 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.output.stroke);
  const outGrp = startGroup(_g, STEP_GROUPS.output, 7);
  const outHeaderBottom = stepHeader(outGrp, CX_R, yR, 7, 'Output hidden states', 'out ∈ ℝ^(S×D)', COLORS.output.fill, COLORS.output.stroke);
  const outCy = outHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(outGrp, CX_R - 80, outCy, 'out', '[S, D]', COLORS.output.fill, COLORS.output.stroke);
  yR = outCy + MAT_H / 2 + GROUP_GAP;

  return { steps, leftBottom: yL, rightTop, rightBottom: yR };
}

function renderSwitch(_g: Gsel, leftTop: number, rightTop: number, nExperts: number): RenderResult {
  const steps: MoERouterStep[] = [];
  let yL = leftTop;
  let yR = rightTop;

  // ── Left column ──

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = startGroup(_g, STEP_GROUPS.input, 1);
  const inHeaderBottom = stepHeader(inputGrp, CX_L, yL, 1, 'Input hidden states', 'x ∈ ℝ^(S×D)', COLORS.input.fill, COLORS.input.stroke);
  const inCy = inHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(inputGrp, CX_L - 80, inCy, 'x', '[S, D]', COLORS.input.fill, COLORS.input.stroke);
  lbl(inputGrp, CX_L, inCy + MAT_H / 2 + 18, 'each row = one token embedding', { size: 12, color: COLORS.muted });
  yL = inCy + MAT_H / 2 + 28;

  // 2. Gate projection
  steps.push({ ...BASE_STEPS.gate, id: 2 });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.gate.stroke);
  yL += GROUP_GAP;
  const gateGrp = startGroup(_g, STEP_GROUPS.gate, 2);
  const gateHeaderBottom = stepHeader(gateGrp, CX_L, yL, 2, 'Gate projection', 'logits = x · W_gate', COLORS.gate.fill, COLORS.gate.stroke);
  const gateRowCy = gateHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  const gateBottom = drawMatmulRow(
    gateGrp, CX_L, gateRowCy,
    'x', '[S, D]', COLORS.input.fill, COLORS.input.stroke,
    'W_gate', '[D, E]', COLORS.weight.fill, COLORS.weight.stroke,
    'logits', '[S, E]', COLORS.gate.fill, COLORS.gate.stroke,
    '[S, D] @ [D, E] → [S, E]'
  );
  yL = gateBottom + GROUP_GAP;

  // 3. Softmax
  steps.push({ ...BASE_STEPS.softmax, id: 3 });
  arrowDown(_g, CX_L, yL - GROUP_GAP, yL, COLORS.softmax.stroke);
  const softmaxGrp = startGroup(_g, STEP_GROUPS.softmax, 3);
  const softmaxHeaderBottom = stepHeader(softmaxGrp, CX_L, yL, 3, 'Softmax over experts', 'probs = softmax(logits, dim=-1)', COLORS.softmax.fill, COLORS.softmax.stroke);
  const softmaxVecCy = softmaxHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(softmaxGrp, CX_L - 80, softmaxVecCy, 'logits', '[S, E]', COLORS.gate.fill, COLORS.gate.stroke);
  arrowDown(softmaxGrp, CX_L, softmaxVecCy + VEC_H / 2, softmaxVecCy + VEC_H / 2 + 24, COLORS.softmax.stroke);
  const softmaxMatCy = softmaxVecCy + VEC_H / 2 + 24 + MAT_H / 2;
  drawScoreMatrix(softmaxGrp, CX_L - 80, softmaxMatCy, 'probs', '[S, E]', COLORS.softmax.fill, COLORS.softmax.stroke);
  lbl(softmaxGrp, CX_L, softmaxMatCy + MAT_H / 2 + 18, 'each row sums to 1.0 across experts', { size: 11, color: COLORS.muted });
  yL = softmaxMatCy + MAT_H / 2 + 28;

  // 4. Top-1 selection
  steps.push({
    ...BASE_STEPS.topk,
    id: 4,
    label: 'Top-1 selection',
    shortLabel: 'Top-1',
    formula: 'index = argmax(probs)',
    explanation: 'Switch routing assigns each token to exactly one expert (top-1).',
    code: { title: 'Top-1', lines: ['index = probs.argmax(dim=-1)  # [S]'] },
  });
  arrowDown(_g, CX_L, yL, yL + GROUP_GAP, COLORS.topk.stroke);
  yL += GROUP_GAP;
  const topkGrp = startGroup(_g, STEP_GROUPS.topk, 4);
  const topkHeaderBottom = stepHeader(topkGrp, CX_L, yL, 4, 'Top-1 selection', 'index = argmax(probs)', COLORS.topk.fill, COLORS.topk.stroke);
  const topkMatCy = topkHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawTopKMatrix(topkGrp, CX_L, topkMatCy, 'probs', '[S, E]', COLORS.softmax.fill, COLORS.softmax.stroke, 1, false);
  const vecCy = topkMatCy + MAT_H / 2 + ROW_EQ_GAP + 18;
  drawSmallVector(topkGrp, CX_L - 80, vecCy, 'index', '[S]', COLORS.topk.fill, COLORS.topk.stroke);
  lbl(topkGrp, CX_L, vecCy + 32, 'one expert per token', { size: 12, color: COLORS.muted, font: 'monospace' });
  yL = vecCy + 48 + GROUP_GAP;

  // ── Right column ──

  // 5. Dispatch
  steps.push({
    ...BASE_STEPS.dispatch,
    id: 5,
    formula: 'tokens → single expert',
    explanation: 'Each token is routed to its single selected expert.',
    code: { title: 'Dispatch', lines: ['for each token s:', '    dispatch x[s] to expert_index[s]'] },
  });
  const dispatchGrp = startGroup(_g, STEP_GROUPS.dispatch, 5);
  const dispatchHeaderBottom = stepHeader(dispatchGrp, CX_R, yR, 5, 'Dispatch to one expert', 'tokens → single expert', COLORS.dispatch.fill, COLORS.dispatch.stroke);
  const expertY = dispatchHeaderBottom + HEADER_TO_ROW_GAP + 22;
  drawDispatchArrows(dispatchGrp, CX_R, dispatchHeaderBottom + HEADER_TO_ROW_GAP, expertY, nExperts);
  const expertBottom = drawExpertBoxes(dispatchGrp, CX_R, expertY, nExperts);
  yR = expertBottom + GROUP_GAP;

  // 6. Combine
  steps.push({
    ...BASE_STEPS.combine,
    id: 6,
    formula: 'out = expert_index(s)(x)',
    explanation: 'The selected expert output becomes the token output directly.',
    code: { title: 'Combine', lines: ['out[s] = experts[index[s]](x[s])  # [S, D]'] },
  });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.combine.stroke);
  const combineGrp = startGroup(_g, STEP_GROUPS.combine, 6);
  const combineHeaderBottom = stepHeader(combineGrp, CX_R, yR, 6, 'Selected expert output', 'out = expert_index(x)', COLORS.combine.fill, COLORS.combine.stroke);
  const combineCy = combineHeaderBottom + HEADER_TO_ROW_GAP + VEC_H / 2;
  const combineBottom = drawCombineRow(combineGrp, CX_R, combineCy, nExperts, 1);
  yR = combineBottom + GROUP_GAP;

  // 7. Output
  steps.push({ ...BASE_STEPS.output, id: 7 });
  arrowDown(_g, CX_R, yR - GROUP_GAP, yR, COLORS.output.stroke);
  const outGrp = startGroup(_g, STEP_GROUPS.output, 7);
  const outHeaderBottom = stepHeader(outGrp, CX_R, yR, 7, 'Output hidden states', 'out ∈ ℝ^(S×D)', COLORS.output.fill, COLORS.output.stroke);
  const outCy = outHeaderBottom + HEADER_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(outGrp, CX_R - 80, outCy, 'out', '[S, D]', COLORS.output.fill, COLORS.output.stroke);
  yR = outCy + MAT_H / 2 + GROUP_GAP;

  return { steps, leftBottom: yL, rightTop, rightBottom: yR };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderMoeRouterDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: import('../../components/types').ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const seqLen = Number(params.seq_len) || 128;
  const nExperts = Number(params.n_experts) || 4;
  const topK = Number(params.top_k) || 2;
  const routing = String(params.routing || 'token-choice');

  const root = g as unknown as Gsel;
  let y = 30;

  // Title
  lbl(root, CX, y, 'MoE Router', { size: 20, weight: '700', color: COLORS.text });
  y += 24;
  lbl(root, CX, y, `${routing.replace(/-/g, ' ')} routing  ·  d_model=${dModel}  seq_len=${seqLen}  n_experts=${nExperts}  top_k=${topK}`, {
    size: 12,
    color: COLORS.muted,
  });
  y += 30;

  // Param summary
  y = drawParamSummary(root, CX, y, dModel, seqLen, nExperts, topK, routing);
  y += 22;

  const columnTop = y;

  // Variant-specific diagram
  let result: RenderResult;
  switch (routing) {
    case 'expert-choice':
      result = renderExpertChoice(root, columnTop, columnTop, nExperts, topK);
      break;
    case 'switch':
      result = renderSwitch(root, columnTop, columnTop, nExperts);
      break;
    case 'token-choice':
    default:
      result = renderTokenChoice(root, columnTop, columnTop, nExperts, topK);
      break;
  }

  // Cross-column arrow from routing decision to dispatch
  const crossLabel = routing === 'expert-choice' ? 'dispatch selected tokens' : 'dispatch selected experts';
  crossColumnArrow(root, result.leftBottom - GROUP_GAP / 2, result.rightTop + HEADER_H / 2, crossLabel);

  // Continue footer from the taller column
  let footerY = Math.max(result.leftBottom, result.rightBottom) + 20;

  // Footer summary
  const gateParams = dModel * nExperts;
  const summaryGrp = root.append('g');
  lbl(summaryGrp, CX, footerY + 18, `Router params: ${fmtNum(gateParams)} (W_gate [D, E])`, {
    size: 11,
    color: COLORS.muted,
  });
  footerY += 38;

  // Side-by-side explanations to save vertical space
  const insightW = (W - 200) / 2;
  const insightY = drawExplanation(g, 80, footerY, insightW - 20,
    'The MoE router decides which experts process each token. Token-choice routing lets each token pick its own top-k experts. ' +
    'Expert-choice routing lets each expert pick its own top-k tokens, guaranteeing balanced load. Switch uses top-1 for maximum sparsity.',
    'insight'
  );
  const perfY = drawExplanation(g, 80 + insightW, footerY, insightW - 20,
    `Router FLOPs per token: ~${fmtNum(2 * dModel * nExperts)} (gate projection). ` +
      'The router is cheap compared to expert FFNs, but its decisions determine which experts are active and therefore ' +
      'how evenly the workload is balanced across devices.',
    'perf'
  );
  footerY = Math.max(insightY, perfY) + 18;

  // Cross-link
  drawComponentLink(g, CX - 90, footerY, 180, 32, 'moe-layer', 'View MoE Layer ↗', {
    fill: '#ede9fe',
    stroke: '#7c3aed',
  });
  footerY += 50;

  // Code annotation
  const codeLines = buildCodeLines(routing, dModel, nExperts, topK);
  footerY = drawCodeAnnotation(
    g,
    80,
    footerY,
    W - 160,
    `MoE Router — ${routing.replace(/-/g, ' ').toUpperCase()}`,
    [`Gate params: ${fmtNum(gateParams)}. Router FLOPs per token: ~${fmtNum(2 * dModel * nExperts)}.`],
    codeLines
  );

  return { width: W, height: footerY + 24, steps: result.steps };
}

function buildCodeLines(routing: string, dModel: number, nExperts: number, topK: number): string[] {
  switch (routing) {
    case 'expert-choice':
      return [
        `self.W_gate = nn.Linear(${dModel}, ${nExperts}, bias=False)`,
        '',
        'def forward(self, x):',
        '    logits = self.W_gate(x)            # [S, E]',
        '    probs = F.softmax(logits, dim=0)   # [S, E]  tokens → experts',
        `    weights, indices = probs.T.topk(${topK}, dim=-1)  # [E, ${topK}]`,
        '    out = self.dispatch_and_combine(x, indices, weights)',
        '    return out',
      ];
    case 'switch':
      return [
        `self.W_gate = nn.Linear(${dModel}, ${nExperts}, bias=False)`,
        '',
        'def forward(self, x):',
        '    logits = self.W_gate(x)            # [S, E]',
        '    probs = F.softmax(logits, dim=-1)  # [S, E]',
        '    index = probs.argmax(dim=-1)       # [S]',
        '    out = self.experts[index](x)       # [S, D]',
        '    return out',
      ];
    case 'token-choice':
    default:
      return [
        `self.W_gate = nn.Linear(${dModel}, ${nExperts}, bias=False)`,
        '',
        'def forward(self, x):',
        '    logits = self.W_gate(x)            # [S, E]',
        '    probs = F.softmax(logits, dim=-1)  # [S, E]',
        `    weights, indices = probs.topk(${topK}, dim=-1)  # [S, ${topK}]`,
        '    out = self.dispatch_and_combine(x, indices, weights)',
        '    return out',
      ];
  }
}
